_SIGNER = None
def signer():
    global _SIGNER
    if not _SIGNER:
        _, _SIGNER = get_oci_signer(OCI_PROFILE)
    return _SIGNER


def _download_path_variants(path: str) -> list:
    """Generate path variants to try when downloading.

    AIDP file names may differ from how they're referenced in code:
      - Original: "HelperLib Monitoring revamp" (with spaces, no .ipynb)
      - Code reference may use: "HelperLib_Monitoring_revamp.ipynb"
    Try all combinations of {as-is, +.ipynb, -.ipynb} ×
    {as-is, spaces↔underscores}, followed by the canonical AIDP-sanitized
    filename variants used when exported resources are uploaded.
    Order: most likely first (as-is, then add .ipynb, then transform).
    """
    variants = []
    seen = set()
    def add(p):
        if p and p not in seen:
            variants.append(p)
            seen.add(p)

    # 1. As-is
    add(path)
    # 2. Add .ipynb if missing
    if not path.endswith(".ipynb"):
        add(path + ".ipynb")
    # 3. Strip .ipynb if present (some AIDP files have no extension)
    if path.endswith(".ipynb"):
        add(path[:-6])
    # 4. Spaces → underscores (and combinations)
    if " " in path:
        u = path.replace(" ", "_")
        add(u)
        if not u.endswith(".ipynb"):
            add(u + ".ipynb")
    # 5. Underscores → spaces (try if no original spaces)
    if "_" in path and " " not in path:
        s = path.replace("_", " ")
        add(s)
        if not s.endswith(".ipynb"):
            add(s + ".ipynb")
        if s.endswith(".ipynb"):
            add(s[:-6])

    def export_relative_suffix(candidate: str) -> Optional[tuple[str, str]]:
        """Split an exported path without rewriting its configured root.

        Exporter sanitization applies to the source-notebook suffix below
        ``EXPORT_BASE``. Applying it to an arbitrary workspace path can bind a
        missing raw notebook (for example ``A+B.ipynb``) to an unrelated
        ``A_B.ipynb``. Sanitizing the configured export root itself also
        diverges from the path dbx_export actually wrote when that root
        contains a character such as ``+``.
        """
        configured = str(EXPORT_BASE or "").replace("\\", "/").rstrip("/")
        if not configured:
            return None

        path_forms = [configured]
        if configured.startswith("/Workspace/"):
            path_forms.append(configured[len("/Workspace/"):])
        elif configured.startswith("Workspace/"):
            path_forms.append("/" + configured)
            path_forms.append(configured[len("Workspace/"):])
        else:
            path_forms.append("/Workspace/" + configured.lstrip("/"))
            path_forms.append("Workspace/" + configured.lstrip("/"))

        for prefix in dict.fromkeys(path_forms):
            boundary = prefix + "/"
            if candidate.startswith(boundary):
                return candidate[:len(prefix)], candidate[len(boundary):]
        return None

    # Match the exporter's notebook contract only inside EXPORT_BASE: strip
    # the extension from the notebook-relative suffix, sanitize its segments,
    # then restore ``.ipynb``. Raw/non-export paths deliberately get no
    # canonical alias.
    for candidate in list(variants):
        export_parts = export_relative_suffix(candidate)
        if export_parts is None:
            continue
        export_prefix, relative = export_parts
        has_extension = relative.lower().endswith(".ipynb")
        relative_stem = relative[:-6] if has_extension else relative
        try:
            sanitized = sanitize_path(relative_stem)
        except ValueError as exc:
            tprint(f"[WARN] omitted invalid sanitized download alias for {candidate!r}: {exc}; retaining original read candidates")
            continue
        if sanitized:
            add(f"{export_prefix}/{sanitized}{'.ipynb' if has_extension else ''}")
    return variants


def download_notebook(path: str, max_retries: int = 3) -> Optional[bytes]:
    """Download a notebook from AIDP workspace with retry + backoff.

    Tries multiple path variants since AIDP file names may differ from how
    they're referenced (spaces vs underscores, with/without .ipynb).
    """
    variants = _download_path_variants(path)
    for attempt_path in variants:
        for retry in range(max_retries):
            try:
                headers = {"Content-Type": "application/json", "path": attempt_path, "type": "NOTEBOOK"}
                print(f"[download] POST {DOWNLOAD_META_URL} path={attempt_path!r} (attempt {retry+1}/{max_retries})")
                resp = http_requests.post(DOWNLOAD_META_URL, auth=signer(), headers=headers, data="",
                                          timeout=60)
                print(f"[download] downloadFileMeta status={resp.status_code} body={resp.text[:300]!r}")
                if resp.status_code == 429:
                    wait = min(10 * (retry + 1), 30)
                    print(f"[download] rate limited (429), waiting {wait}s before retry")
                    time.sleep(wait)
                    continue
                if resp.status_code != 200:
                    break  # not retryable, try next path variant
                par_url = resp.json().get("parUrl")
                if not par_url:
                    print(f"[download] no parUrl in response")
                    break
                resp = http_requests.get(par_url, timeout=60)
                print(f"[download] PAR GET status={resp.status_code} content_len={len(resp.content)}")
                if resp.status_code == 429:
                    wait = min(10 * (retry + 1), 30)
                    print(f"[download] PAR rate limited (429), waiting {wait}s before retry")
                    time.sleep(wait)
                    continue
                if resp.status_code == 200 and len(resp.content) > 10:
                    return resp.content
            except Exception as e:
                print(f"[download] exception for path={attempt_path!r} (attempt {retry+1}/{max_retries}): {e}")
                if retry < max_retries - 1:
                    wait = min(5 * (retry + 1), 15)
                    print(f"[download] retrying in {wait}s...")
                    time.sleep(wait)
                continue
    print(f"[download] FAILED — all {len(variants)} path variants exhausted for {path!r}: tried {variants}")
    return None


async def download_notebook_async(path: str) -> Optional[bytes]:
    """Non-blocking wrapper: runs download_notebook in a thread pool."""
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(None, download_notebook, path)


